using UnityEngine;
public class SimpleRaycast:MonoBehaviour{public float rayDistance=10f;public bool showDebug=true;void Update(){if(!showDebug)return;Ray ray=new Ray(transform.position,transform.forward);if(Physics.Raycast(ray,out RaycastHit hit,rayDistance))Debug.Log("Ray hit: "+hit.collider.gameObject.name);}void OnDrawGizmos(){Ray ray=new Ray(transform.position,transform.forward);if(Physics.Raycast(ray,out RaycastHit hit,rayDistance)){Gizmos.color=Color.green;Gizmos.DrawRay(transform.position,transform.forward*hit.distance);Gizmos.color=Color.yellow;Gizmos.DrawWireSphere(hit.point,.12f);}else{Gizmos.color=Color.red;Gizmos.DrawRay(transform.position,transform.forward*rayDistance);}}}
